//! The perfect-freehand port against the outlines the npm package produced
//! (`crates/ink/golden/vectors.json`, generated by `generate.mjs` with perfect-freehand 1.2.3).
//! Same point count per case and every coordinate within `TOLERANCE` of upstream's value
//! after the generator's rounding to six decimals.

use openlogos_ink::{EndOptions, InputPoint, StrokeOptions, Taper, get_stroke};
use serde::Deserialize;

const VECTORS: &str = include_str!("../golden/vectors.json");
const TOLERANCE: f64 = 1e-5;

#[derive(Deserialize)]
struct Vectors {
    upstream: Upstream,
    cases: Vec<Case>,
}

#[derive(Deserialize)]
struct Upstream {
    name: String,
    version: String,
    license: String,
}

#[derive(Deserialize)]
struct Case {
    name: String,
    options: Options,
    points: Vec<(f64, f64, Option<f64>)>,
    outline: Vec<(f64, f64)>,
}

#[derive(Deserialize, Default)]
#[serde(rename_all = "camelCase")]
struct Options {
    size: Option<f64>,
    thinning: Option<f64>,
    smoothing: Option<f64>,
    streamline: Option<f64>,
    simulate_pressure: Option<bool>,
    last: Option<bool>,
    start: Option<End>,
    end: Option<End>,
}

#[derive(Deserialize, Default)]
struct End {
    cap: Option<bool>,
    taper: Option<serde_json::Value>,
}

fn taper(value: Option<&serde_json::Value>) -> Taper {
    match value {
        None | Some(serde_json::Value::Bool(false)) => Taper::None,
        Some(serde_json::Value::Bool(true)) => Taper::Full,
        Some(serde_json::Value::Number(n)) => Taper::Distance(n.as_f64().unwrap_or(0.0)),
        Some(other) => panic!("unexpected taper {other}"),
    }
}

fn end(given: Option<&End>, default: EndOptions) -> EndOptions {
    let Some(given) = given else { return default };
    EndOptions {
        cap: given.cap.unwrap_or(default.cap),
        taper: taper(given.taper.as_ref()),
        easing: default.easing,
    }
}

fn options(o: &Options) -> StrokeOptions {
    let d = StrokeOptions::default();
    StrokeOptions {
        size: o.size.unwrap_or(d.size),
        thinning: o.thinning.unwrap_or(d.thinning),
        smoothing: o.smoothing.unwrap_or(d.smoothing),
        streamline: o.streamline.unwrap_or(d.streamline),
        easing: d.easing,
        simulate_pressure: o.simulate_pressure.unwrap_or(d.simulate_pressure),
        start: end(o.start.as_ref(), d.start),
        end: end(o.end.as_ref(), d.end),
        last: o.last.unwrap_or(d.last),
    }
}

#[test]
fn the_port_reproduces_upstream_outlines() {
    let vectors: Vectors = serde_json::from_str(VECTORS).expect("vectors.json parses");
    assert_eq!(vectors.upstream.name, "perfect-freehand");
    assert_eq!(vectors.upstream.version, "1.2.3");
    assert_eq!(vectors.upstream.license, "MIT");
    assert!(vectors.cases.len() >= 10);

    let mut worst = 0.0_f64;
    for case in &vectors.cases {
        let points: Vec<InputPoint> = case
            .points
            .iter()
            .map(|&(x, y, p)| InputPoint::new(x, y, p))
            .collect();
        let outline = get_stroke(&points, &options(&case.options));
        assert_eq!(
            outline.len(),
            case.outline.len(),
            "{}: point count differs from upstream",
            case.name
        );
        for (i, (ours, &(ux, uy))) in outline.iter().zip(&case.outline).enumerate() {
            let dx = (ours[0] - ux).abs();
            let dy = (ours[1] - uy).abs();
            worst = worst.max(dx).max(dy);
            assert!(
                dx <= TOLERANCE && dy <= TOLERANCE,
                "{} point {i}: ours ({}, {}) upstream ({ux}, {uy})",
                case.name,
                ours[0],
                ours[1]
            );
        }
    }
    eprintln!(
        "golden: {} cases, worst coordinate difference {worst:e}",
        vectors.cases.len()
    );
}
